import io

def parse_csv_line(line: str) -> list[str]:
    """Split one CSV line on commas. Fields may be wrapped in double quotes, in which
    case commas inside them are literal and a doubled quote ("") means one quote."""
    # Use Python's csv module for correct handling per RFC 4180
    if line == "":
        return [""]
    reader = csv.reader(io.StringIO(line), quotechar='"', quoting=csv.QUOTE_MINIMAL, doublequote=True, skipinitialspace=False)
    try:
        row = next(reader)
    except StopIteration:
        return [""]
    return row
"}

